import{z as B,x as p,o as s,c as g,q as l,j as r,D as i,d as E,s as t,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"CES 与 Cobb–Douglas","description":"","frontmatter":{"title":"CES 与 Cobb–Douglas","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ces-cobb-douglas.md","filePath":"econ/ces-cobb-douglas.md","lastUpdated":1791063341000}'),C={name:"econ/ces-cobb-douglas.md"};function m(A,a,b,d,u,D){const e=p("Mermaid");return s(),g("div",null,[a[2]||(a[2]=l('<h1 id="ces-与-cobb–douglas" tabindex="-1">CES 与 Cobb–Douglas <a class="header-anchor" href="#ces-与-cobb–douglas" aria-label="Permalink to &quot;CES 与 Cobb–Douglas&quot;">​</a></h1><div class="epigraph"><p>替代弹性一旦被钉成常数，份额随相对价格怎么走就只剩一个数字；那个数字等于一，就是 Cobb–Douglas。</p><footer>—— 据 Varian, Microeconomic Analysis；Mas-Colell, Whinston and Green, Microeconomic Theory 第 3 章整理</footer></div><p><a href="/econ/quasilinear-homothetic">上一课</a>给出拟线性与位似两条刀：零收入效应，或需求对财富一次齐次。本课不重写这两种结构，也不把 Debreu 表示再证一遍。缺口是：位似只说扩张路径是射线，没有给出<strong>替代弹性</strong>这个标量。后课算例、份额语言、Dixit–Stiglitz 式加总，都要一条可算的位似族。CES 把 \\(\\sigma\\) 钉成常数；\\(\\sigma=1\\) 的刀刃就是 Cobb–Douglas。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>位似保证 \\(x(p,w)=w\\,x(p,1)\\)，支出份额只靠价格。份额<strong>如何</strong>随 \\(p_i/p_j\\) 变，一般位似仍任意。若每次换题目就换一条无差异曲线的弯曲，后课无法写「替代弹性为常数」的比较静态，也无法认出教科书里那条对数可加的 \\(u\\)。缺口不是再声明一次位似，而是引入常替代弹性（CES）</p> \\[u(x)=\\Bigl(\\sum_i\\alpha_i x_i^{\\rho}\\Bigr)^{1/\\rho},\\qquad \\sigma=\\frac{1}{1-\\rho}, \\]<p>\\(\\alpha_i\\gt 0\\)，\\(\\rho\\lt 1\\)，\\(\\rho\\neq 0\\)。\\(\\sigma\\) 是任意两商品之间的替代弹性，与点无关——这比「位似」窄得多。本课的任务是读 \\(\\sigma\\) 的三个极限，并钉死 \\(\\sigma=1\\) 不是另一条效用，而是 CES 的极限。</p><p><span class="marginnote">替代弹性 \\(\\sigma\\) 可以翻译成「换牌子的难易度」：可口可乐涨价 1%，你改买百事的比例变多少。\\(\\sigma\\) 大＝随手可换（近替代品），\\(\\sigma\\) 小＝换不了（左脚鞋配右脚鞋）。CES 就是把这个难易度钉成全局唯一一个数，不再随消费点漂移。</span></p><h3 id="份额恒定不是另一条公理" tabindex="-1">份额恒定不是另一条公理 <a class="header-anchor" href="#份额恒定不是另一条公理" aria-label="Permalink to &quot;份额恒定不是另一条公理&quot;">​</a></h3><p>\\(\\rho\\to 0\\) 时，\\(u\\) 趋向 Cobb–Douglas \\(\\prod_i x_i^{\\alpha_i}\\)（差单调变换）。此时支出份额 \\(p_i x_i/w=\\alpha_i/\\sum\\alpha_k\\)，与相对价格无关。份额恒定是 \\(\\sigma=1\\) 的推论，不是与 CES 并列的第三种偏好。上一课已经声明 Cobb–Douglas 位似且非拟线性；本课只补它在 CES 族里的位置。</p><p><span class="marginnote">生产课的 CES（Arrow–Chenery–Minhas–Solow）是同一函数形式换到 \\(f(z)\\)。本课对象仍是消费者 \\(u\\)，不要把要素替代弹性写成马歇尔需求。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定 CES，内点马歇尔需求由一阶条件直接解。两种商品时</p> \\[\\frac{x_i}{x_j}=\\Bigl(\\frac{\\alpha_i}{\\alpha_j}\\Bigr)^{\\sigma}\\Bigl(\\frac{p_i}{p_j}\\Bigr)^{-\\sigma}. \\]<p>相对需求对相对价格的弹性就是 \\(-\\sigma\\)。\\(\\sigma\\to\\infty\\)（\\(\\rho\\to 1\\)）线性效用，完全替代，角点只买更便宜的。\\(\\sigma\\to 0\\)（\\(\\rho\\to-\\infty\\)）Leontief，完全互补，比例锁死。中间任意 \\(\\sigma\\) 仍位似：涨 \\(w\\) 只缩放，不改 \\(x_i/x_j\\)。</p><p>Cobb–Douglas 用对数一阶条件 \\(x_i=\\alpha_i w/p_i\\)（份额归一后），不必经过 \\(\\rho\\) 的极限运算也能算。CES 的价值是把这条需求嵌进同一条 \\(\\sigma\\) 轴，而不是再发明一种效用。</p>',16)),(s(),r(n,null,{default:i(()=>[t(e,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOM%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E4%BD%8D%E4%BC%BC%22%5D%20--%3E%20CES%5B%22CES%EF%BC%9A%CF%83%20%E4%B8%BA%E5%B8%B8%E6%95%B0%22%5D%0A%20%20CES%20--%3E%20CD%5B%22%CF%83%20%3D%201%EF%BC%9ACobb%E2%80%93Douglas%22%5D%0A%20%20CES%20--%3E%20LEO%5B%22%CF%83%20%E2%86%92%200%EF%BC%9ALeontief%22%5D%0A%20%20CES%20--%3E%20LIN%5B%22%CF%83%20%E2%86%92%20%E2%88%9E%EF%BC%9A%E7%BA%BF%E6%80%A7%22%5D%0A%20%20CD%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%BB%BD%E9%A2%9D%E7%AE%97%E4%BE%8B%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"拟线性不在这条轴上。CES 的收入效应沿射线，不能把收入赶到计价物。三种形状上一课已经分开；本课见到 Cobb–Douglas 先问 \\(\\sigma=1\\)，不要问它是不是拟线性。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[E("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"\\(\\sigma\\) 管的是沿无差异面滑动的难易。\\(\\sigma\\) 大，相对价格一动，数量比猛调，支出份额跟着相对变贵的商品走（份额弹性为 \\(1-\\sigma\\)）。\\(\\sigma=1\\)，数量比刚好抵消价格比，份额钉住。\\(\\sigma\\lt 1\\)，数量调不动，份额反而涌向变贵的商品——这是互补的支出面，不是吉芬。",-1)),(s(),r(n,null,{default:i(()=>[t(e,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%9B%B8%E5%AF%B9%E4%BB%B7%E6%A0%BC%20p_i%2Fp_j%20%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20S1%5B%22%CF%83%20%3E%201%EF%BC%9A%E6%95%B0%E9%87%8F%E6%AF%94%E5%A4%A7%E5%B9%85%E8%B0%83%E6%95%B4%22%5D%0A%20%20S1%20--%3E%20H1%5B%22%E4%BB%BD%E9%A2%9D%E6%B5%81%E5%90%91%E5%8F%98%E4%BE%BF%E5%AE%9C%E7%9A%84%E5%95%86%E5%93%81%22%5D%0A%20%20P%20--%3E%20S2%5B%22%CF%83%20%3D%201%EF%BC%9A%E6%95%B0%E9%87%8F%E6%AF%94%E6%81%B0%E5%A5%BD%E6%8A%B5%E6%B6%88%E4%BB%B7%E6%A0%BC%E6%AF%94%22%5D%0A%20%20S2%20--%3E%20H2%5B%22%E4%BB%BD%E9%A2%9D%E9%92%89%E4%BD%8F%E4%B8%8D%E5%8F%98%EF%BC%9ACobb%E2%80%93Douglas%22%5D%0A%20%20P%20--%3E%20S3%5B%22%CF%83%20%3C%201%EF%BC%9A%E6%95%B0%E9%87%8F%E8%B0%83%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20S3%20--%3E%20H3%5B%22%E4%BB%BD%E9%A2%9D%E5%8F%8D%E8%80%8C%E6%B6%8C%E5%90%91%E5%8F%98%E8%B4%B5%E5%95%86%E5%93%81%EF%BC%9A%E4%BA%92%E8%A1%A5%E6%94%AF%E5%87%BA%E9%9D%A2%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">代入数字感受三分支：取 \\(p_i/p_j\\) 翻倍。\\(\\sigma=2\\) 时数量比 \\(x_i/x_j\\) 降到原来的 \\(1/4\\)，份额追着涨价商品的反面跑；\\(\\sigma=1\\) 时数量比同样减半，恰好抵消价格，份额纹丝不动；\\(\\sigma=1/2\\) 时数量比只降到约 71%，份额反而偏向变贵的商品。同一涨价，三种份额命运。</span></p><p>位似保证所有商品收入弹性为 \\(1\\)，故 CES 与 Cobb–Douglas 都排除劣等，因而排除吉芬。后课<a href="/econ/slutsky-equation">斯勒茨基</a>的收入项与 \\(x\\) 成比例，正是因为走在这一族里。一般 \\(u\\) 没有常数 \\(\\sigma\\)，交叉替代随点变，份额语言失效。</p><p><span class="marginnote">\\(\\alpha_i\\) 是份额权重，不是「重要性」的基数度量。序数性上一课已有：单调变换改变 \\(\\rho\\) 的写法，但不改变 \\(\\sigma\\) 与需求。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CES 要求所有成对替代弹性相同。经验上食品与奢侈品的 \\(\\sigma\\) 不必相等；那是更一般的位似或非位似。Stone–Geary 把 Cobb–Douglas 平移出原点，恩格尔不过原点，替代弹性也不再全局为 \\(1\\)。本课不把拟位似提前写完。</p><p><span class="marginnote">常见误区：以为「份额涌向变贵商品」是吉芬现象。吉芬品需要收入效应压过替代效应，而 CES 全族收入弹性为 \\(1\\)、排除劣等品；这里的份额反向是 \\(\\sigma\\lt 1\\) 的互补支出面——数量调不动，钱只好跟着价格走。两件事机制不同，不要混。</span></p><p>也不要把 CES 写成限价簿上的流动性替代：这里没有报价，只有确定消费束。后课垄断竞争会借用 CES 加总，那是厂商课的 Dixit–Stiglitz，对象从个人 \\(u\\) 换成产品指数，本课不预支。</p><p>后课默认：见到 CES，就把它当常 \\(\\sigma\\) 的位似；见到 Cobb–Douglas，先当成 \\(\\sigma=1\\) 的 CES 特例，份额恒定、收入弹性为 \\(1\\)。一般需求理论不默认这条族。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>位似不蕴含常替代弹性；CES 把 \\(\\sigma\\) 钉成与点无关的常数。</li><li>\\(\\sigma=1\\) 是 Cobb–Douglas：支出份额与相对价格无关。</li><li>\\(\\sigma\\to 0\\) 互补，\\(\\sigma\\to\\infty\\) 完全替代；三者同一条轴，不是三种偏好。</li><li>CES 排除劣等与吉芬；拟线性是另一把刀。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Mas-Colell, Whinston and Green 第 3 章。</li></ul>',10))])}const c=B(C,[["render",m]]);export{_ as __pageData,c as default};
